def choose_move(observation):
    w = observation.get("grid_width", 8)
    h = observation.get("grid_height", 8)
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [0, 0])

    obstacles = observation.get("obstacles") or []
    obs = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            obs.add((p[0], p[1]))

    def valid(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obs

    deltas = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
    moves = []
    for dx, dy in deltas:
        nx, ny = sx + dx, sy + dy
        if valid(nx, ny):
            moves.append((dx, dy, nx, ny))

    def manh(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    best = None
    for dx, dy, nx, ny in moves:
        worst = -1
        # opponent maximizes distance to us on its turn (worst-case)
        for odx, ody in deltas:
            nox, noy = ox + odx, oy + ody
            if not valid(nox, noy):
                continue
            d = manh(nx, ny, nox, noy)
            if d > worst:
                worst = d
        # if opponent has no legal moves (rare), treat as staying
        if worst < 0:
            worst = manh(nx, ny, ox, oy)
        curdist = manh(nx, ny, ox, oy)
        score = (worst, curdist, -abs(dx) - abs(dy), dx, dy)
        if best is None or score < best[0]:
            best = (score, dx, dy)

    if best is None:
        return [0, 0]
    return [best[1], best[2]]

def choose_move(observation):
    w = int(observation.get("grid_width", 8))
    h = int(observation.get("grid_height", 8))
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [0, 0])
    obstacles = observation.get("obstacles") or []
    obs = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                obs.add((x, y))

    def inside(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obs

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
    candidates = []
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if inside(nx, ny):
            candidates.append((dx, dy, nx, ny))
    if not candidates:
        return [0, 0]

    def sqdist(x1, y1, x2, y2):
        dx, dy = x1 - x2, y1 - y2
        return dx * dx + dy * dy

    # Pressure heuristic: reduce distance; prefer moves that also "cut off" by limiting opponent escape.
    # Wall-run nerf: prefer staying aligned with opponent's direction (diagonal/axial components).
    best = None
    cur_d = sqdist(sx, sy, ox, oy)

    for dx, dy, nx, ny in candidates:
        d = sqdist(nx, ny, ox, oy)

        # "Escape-limiting": count how many moves from opponent would increase its distance from our new position.
        opp_moves = []
        for adx, ady in moves:
            ax, ay = ox + adx, oy + ady
            if inside(ax, ay):
                opp_moves.append((ax, ay))
        if opp_moves:
            inc = 0
            for ax, ay in opp_moves:
                if sqdist(ax, ay, nx, ny) >= sqdist(ox, oy, nx, ny):
                    inc += 1
            escape_score = inc
        else:
            escape_score = 0

        align = abs((nx - ox)) + abs((ny - oy))  # closer means less
        move_delta = cur_d - d  # positive is good

        # Score: lexicographic on best pressure; deterministic tie-breaks.
        score = (
            d,                 # primary: get close
            escape_score,      # secondary: reduce opponent escape options
            align,             # secondary: keep pressure on approach path
            -move_delta,       # prefer bigger improvement this turn
            (dx != 0) + (dy != 0),  # slight preference for diagonal when equal
            dx, dy
        )
        if best is None or score < best[0]:
            best = (score, dx, dy)

    return [int(best[1]), int(best[2])]

def choose_move(observation):
    w = int(observation.get("grid_width", 8) or 8)
    h = int(observation.get("grid_height", 8) or 8)

    sp = observation.get("self_position") or [0, 0]
    op = observation.get("opponent_position") or [0, 0]
    sx, sy = int(sp[0]), int(sp[1])
    ox, oy = int(op[0]), int(op[1])

    role = str(observation.get("self_role") or "").lower()
    is_evader = ("evad" in role) or ("escap" in role) or ("run" in role) or ("runner" in role)

    blocked = set()
    for p in observation.get("obstacles") or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            bx, by = int(p[0]), int(p[1])
            if 0 <= bx < w and 0 <= by < h:
                blocked.add((bx, by))

    def cheb(x, y):
        ax = abs(x - ox)
        ay = abs(y - oy)
        return ax if ax > ay else ay

    def man(x, y):
        return abs(x - ox) + abs(y - oy)

    def dist(x, y):
        ax = abs(x - ox)
        ay = abs(y - oy)
        return (ax * ax + ay * ay)

    def obstacle_adjacency(x, y):
        c = 0
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if (nx, ny) in blocked:
                    c += 1
        return c

    best = None
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if not (0 <= nx < w and 0 <= ny < h):
                continue
            if (nx, ny) in blocked:
                continue
            c = cheb(nx, ny)
            m = man(nx, ny)
            d = dist(nx, ny)
            adj = obstacle_adjacency(nx, ny)
            if is_evader:
                key = (-c, -m, -d, adj, dx, dy)
            else:
                key = (c, m, d, -adj, dx, dy)
            if best is None or key < best[0]:
                best = (key, dx, dy)

    if best is None:
        return [0, 0]
    return [int(best[1]), int(best[2])]

